"""Independent, synthetic curriculum. No legacy data or credentials."""
import os
from werkzeug.security import generate_password_hash


def seed_database(db):
    password = os.environ.get('CLUB_SEED_PASSWORD')
    if not password or len(password) < 12:
        raise RuntimeError('Set CLUB_SEED_PASSWORD to a private staging password (12+ characters).')
    with db:
        for name, role, entitlement in [('learner', 'learner', 'free'), ('member', 'learner', 'member'), ('revoked', 'learner', 'revoked'), ('editor', 'editor', 'free'), ('admin', 'admin', 'free')]:
            db.execute('INSERT OR IGNORE INTO users(id,email,password_hash,name,role,entitlement) VALUES(?,?,?,?,?,?)',
                       ('user-' + name, name + '@example.test', generate_password_hash(password), {'learner':'Алекс', 'member':'Саша', 'revoked':'Женя', 'editor':'Редактор', 'admin':'Администратор'}[name], role, entitlement))
        courses = [
            ('ai-foundations', 'AI: от вопроса к полезному результату', 'Разберитесь в возможностях AI и подготовьте первый проверенный рабочий ответ.', 'Составите понятный запрос, проверите ответ и сохраните результат для своей задачи.', 'essentials', 'Начальный', 'Любой текстовый AI; бесплатного тарифа достаточно для практики.', 'Опыт не требуется.', 'Учебная команда AI Room'),
            ('everyday-ai', 'Меньше рутины, больше времени', 'Превратите заметки и длинные тексты в конкретный план действий.', 'Подготовите резюме встречи и план с проверяемыми задачами.', 'work', 'Начальный', 'Текстовый AI на ваш выбор. Возможны ограничения бесплатного тарифа.', 'Умение составить простой запрос.', 'Учебная команда AI Room'),
            ('agent-lab', 'Первый управляемый агент', 'Спроектируйте помощника с понятными границами и проверкой результата.', 'Опишете сценарий агента, разрешения и критерии остановки.', 'agents', 'Продвинутый', 'Практика на бумаге; платные сервисы не требуются.', 'Основы промптинга и понимание API.', 'Лаборатория AI Room'),
            ('build-lab', 'Прототип с AI', 'От небольшой идеи к проверяемому прототипу.', 'Создадите спецификацию и план проверки первого прототипа.', 'build', 'Продвинутый', 'Редактор текста; платные сервисы не требуются.', 'Основы AI и опыт работы с цифровыми инструментами.', 'Лаборатория AI Room'),
        ]
        for c in courses:
            db.execute('''INSERT OR IGNORE INTO courses(id,title,description,outcome,goal,level,tools,prerequisites,author,updated_at,status)
                VALUES(?,?,?,?,?,?,?,?,?,'2026-10-02','published')''', c)
        modules = [
            ('start', 'Первый полезный результат', ['Что AI умеет — и где нужна ваша проверка', 'Задача, контекст и формат ответа', 'Уточняем первый ответ', 'Сохраняем результат']),
            ('context', 'Контекст без лишнего', ['Что дать модели на вход', 'Работа с примерами', 'Безопасные учебные данные', 'Проверка ограничений']),
            ('prompts', 'Точные запросы', ['Роль и задача', 'Формат результата', 'Критерии качества', 'Сравнение вариантов']),
            ('verify', 'Проверяем ответы', ['Факты и предположения', 'Ищем подтверждения', 'Работа с числами', 'Признаки ошибки']),
            ('texts', 'Тексты для работы', ['Структура черновика', 'Редактирование тона', 'Краткое резюме', 'Ясность формулировок']),
            ('research', 'Учебное исследование', ['План исследования', 'Вопросы к источнику', 'Сводная таблица', 'Ограничения выводов']),
            ('workflow', 'Личный рабочий процесс', ['Выбираем повторяемую задачу', 'Делим задачу на шаги', 'Точка проверки', 'Сохраняем шаблон']),
            ('quality', 'Улучшаем качество', ['Сравниваем с критериями', 'Собираем замечания', 'Повторная попытка', 'Контрольный пример']),
            ('project', 'Небольшой итоговый проект', ['Выбираем результат', 'Пишем запрос', 'Проверяем ответ', 'Описываем ограничения', 'Сохраняем итоговый результат']),
        ]
        for m_index, (slug, title, titles) in enumerate(modules):
            module_id = 'foundations-' + slug
            db.execute('INSERT OR IGNORE INTO modules VALUES(?,?,?,?)', (module_id, 'ai-foundations', title, m_index))
            for index, title in enumerate(titles):
                first = m_index == 0 and index == 0
                body = ('AI помогает подготовить черновик, но правдоподобный ответ не гарантирует точность. Начните с небольшой задачи: например, превратить учебные заметки в список следующих действий.\n\n'
                        '1. Опишите, какой результат вам нужен и кто будет им пользоваться.\n2. Добавьте безопасный контекст: используйте вымышленные данные вместо личной или рабочей переписки.\n3. Задайте формат ответа — например, таблицу с действием и ожидаемым результатом.\n4. Проверьте каждое утверждение и отметьте то, что требует уточнения.\n\n'
                        'Попробуйте применить тему «' + title + '» к одной своей задаче. Сначала запишите собственный вариант, затем сравните его с ответом AI. Сохраните, что оказалось полезным и что пришлось исправить.\n\n'
                        'Это синтетический учебный материал для проверки новой платформы. Редакционная программа и полноценные авторские видео ещё не опубликованы.')
                db.execute('''INSERT OR IGNORE INTO lessons(id,module_id,title,objective,body,minutes,position,access,video,prompt,task,checklist)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?)''', (
                        f'{module_id}-{index+1:02}', module_id, title, 'Получить небольшой проверенный результат и объяснить его ограничения.', body,
                        6 if first else 8 + index, index, 'free' if m_index == 0 else 'member', 'fixture.webm' if first else None,
                        'Помоги превратить учебные заметки в план. Сначала задай до трёх уточняющих вопросов. Затем предложи таблицу: действие, результат, что нужно проверить. Не придумывай недостающие факты.',
                        'Выберите небольшую задачу. Запишите запрос, краткий результат и одно исправление после проверки. Можно сохранить текст или ссылку на свой документ.',
                        'Результат отвечает исходной задаче\nФакты проверены отдельно\nНет личных или конфиденциальных данных\nУказано хотя бы одно ограничение'))
        for course_id, title, goal in [('everyday-ai', 'Из заметок — в план действий', 'Составить проверяемый план встречи.'), ('agent-lab', 'Границы и разрешения агента', 'Описать безопасные границы автоматизации.'), ('build-lab', 'Проверяемая идея прототипа', 'Определить результат и критерии проверки.')]:
            module_id = course_id + '-intro'
            db.execute('INSERT OR IGNORE INTO modules VALUES(?,?,?,0)', (module_id, course_id, 'Начинаем с задачи'))
            db.execute('''INSERT OR IGNORE INTO lessons(id,module_id,title,objective,body,minutes,position,access,prompt,task,checklist)
                VALUES(?,?,?,?,?,10,0,'free',?,?,?)''', (module_id + '-01', module_id, title, goal,
                'Учебная мастерская: выберите одну конкретную задачу. Запишите входные данные, желаемый результат и способ проверки.\n\nРазделите то, что AI может предложить, и то, что должен подтвердить человек. Не передавайте реальные персональные данные.\n\nСинтетический материал для проверки платформы.',
                'Помоги описать мою задачу: входные данные, результат, ограничения и проверка. Начни с уточнения цели.',
                'Сохраните описание задачи и три критерия готовности.', 'Цель конкретна\nРезультат можно проверить\nОграничения названы'))
